module parity_8bit (
    input [7:0] in,
    output out
);

    reg parity;
    integer i;

    always @(*) begin
        parity = 0;
        for (i = 0; i < 8; i = i + 1) begin
            parity = parity ^ in[i];
        end
    end

    assign out = parity;

endmodule

