module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    code = 2'b00; // Default value
    if (in[3]) code = 2'b11;
    else if (in[2]) code = 2'b10;
    else if (in[1]) code = 2'b01;
    else if (in[0]) code = 2'b00;
end

endmodule

