module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [1:0] current_state, next_state;

    assign state = current_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= 2'b00;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            2'b00: next_state = 2'b01;
            2'b01: next_state = 2'b10;
            2'b10: next_state = 2'b00;
            default: next_state = 2'b00;
        endcase
    end

endmodule

module fsm_3state (
    input clk, reset,
    output reg [1:0] state
);

    reg [1:0] next_state;

    // State encoding
    localparam S0 = 2'b00, 
               S1 = 2'b01, 
               S2 = 2'b10;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Combinational logic for next state computation
    always @(*) begin
        case (state)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0;
        endcase
    end

endmodule

module fsm_3state (
    input clk, reset,
    output reg [1:0] state
);

    // State encoding
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;

    reg [1:0] current_state, next_state;

    // Sequential logic: state transition on clock edge
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Combinational logic: next state calculation
    always @(*) begin
        case (current_state)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0;
        endcase
    end

    // Output logic
    always @(*) begin
        state = current_state;
    end

endmodule

