module int_sqrt (
    input signed [15:0] in_0,
    output signed [7:0] out
);

    reg signed [7:0] result;
    reg signed [15:0] square;
    integer i;

    always @(*) begin
        result = 0;
        square = 0;
        for (i = 7; i >= 0; i = i - 1) begin
            if ((square + ((result | (1 << i)) * (result | (1 << i)))) <= in_0) begin
                result = result | (1 << i);
                square = result * result;
            end
        end
    end

    assign out = result;

endmodule

