module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

    parameter N = 4; // Number of taps
    reg [7:0] x_reg [0:N-1];
    reg [15:0] y_reg [0:N-1];
    reg [7:0] coeff [0:N-1];

    integer i;

    initial begin
        coeff[0] = 8'd1;
        coeff[1] = 8'd2;
        coeff[2] = 8'd3;
        coeff[3] = 8'd4;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < N; i = i + 1) begin
                x_reg[i] <= 8'd0;
                y_reg[i] <= 16'd0;
            end
            y <= 16'd0;
        end else begin
            x_reg[0] <= x;
            for (i = 1; i < N; i = i + 1) begin
                x_reg[i] <= x_reg[i-1];
            end

            y_reg[0] <= x_reg[0] * coeff[0];
            for (i = 1; i < N; i = i + 1) begin
                y_reg[i] <= y_reg[i-1] + (x_reg[i] * coeff[i]);
            end

            y <= y_reg[N-1];
        end
    end

endmodule

