            // Shift input samples through pipeline
            x_reg[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                x_reg[i] <= x_reg[i-1];
            end

            // Multiply samples with coefficients
            for (i = 0; i < 4; i = i + 1) begin
                mult_reg[i] <= x_reg[i] * coeff[i];
            end

            // Add results through pipeline
            add_reg[0] <= mult_reg[0] + mult_reg[1];
            add_reg[1] <= add_reg[0] + mult_reg[2];
            add_reg[2] <= add_reg[1] + mult_reg[3];

