    parameter signed [7:0] c1 = 8'd2;
    parameter signed [7:0] c2 = 8'd3;
    parameter signed [7:0] c3 = 8'd4;
    parameter signed [7:0] c4 = 8'd5;

    // Pipeline registers
    reg [7:0] x_pipe [0:4];
    reg signed [15:0] mul_pipe [0:4];
    reg signed [15:0] add_pipe [0:3];

