        if (rst) begin
            // Reset all pipeline registers
            for (i = 0; i < 5; i = i + 1) begin
                x_pipe[i] <= 8'd0;
                mul_pipe[i] <= 16'd0;
                if (i < 4) add_pipe[i] <= 16'd0;
            end
            y <= 16'd0;
        end else begin
            // Shift input through pipeline
            x_pipe[0] <= x;
            for (i = 1; i < 5; i = i + 1) begin
                x_pipe[i] <= x_pipe[i-1];
            end

            // Multiply with coefficients
            mul_pipe[0] <= x_pipe[0] * c0;
            mul_pipe[1] <= x_pipe[1] * c1;
            mul_pipe[2] <= x_pipe[2] * c2;
            mul_pipe[3] <= x_pipe[3] * c3;
            mul_pipe[4] <= x_pipe[4] * c4;

            // Add results through pipeline
            add_pipe[0] <= mul_pipe[0] + mul_pipe[1];
            add_pipe[1] <= add_pipe[0] + mul_pipe[2];
            add_pipe[2] <= add_pipe[1] + mul_pipe[3];
            add_pipe[3] <= add_pipe[2] + mul_pipe[4];

            // Final output
            y <= add_pipe[3];
        end
    end

