            mult_pipe[0] <= x_pipe[0] * h0;
            mult_pipe[1] <= x_pipe[1] * h1;
            mult_pipe[2] <= x_pipe[2] * h2;
            mult_pipe[3] <= x_pipe[3] * h3;

            // Perform additions in pipeline
            add_pipe[0] <= mult_pipe[0] + mult_pipe[1];
            add_pipe[1] <= add_pipe[0] + mult_pipe[2];
