        coeffs[3] = 8'd4;
    end

    // Pipeline registers for input samples
    reg [7:0] pipeline [0:3];
    reg [15:0] partial_sum [0:3];

    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all pipeline registers and output
            for (i = 0; i < 4; i = i + 1) begin
                pipeline[i] <= 8'd0;
                partial_sum[i] <= 16'd0;
            end
            y <= 16'd0;
