            // Shift input samples through the pipeline
            pipeline[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                pipeline[i] <= pipeline[i-1];
            end

            // Perform multiplication and accumulation
            for (i = 0; i < 4; i = i + 1) begin
                partial_sum[i] <= pipeline[i] * coeffs[i];
            end

            // Compute the final output
            y <= partial_sum[0] + partial_sum[1] + partial_sum[2] + partial_sum[3];
