    reg [7:0] delay_line [0:3];
    reg [15:0] mul_results [0:3];
    reg [15:0] add_stage_1 [0:1];
    reg [15:0] add_stage_2;

    wire [7:0] coeffs [0:3];
    assign coeffs[0] = 8'd1; // Example coefficients
    assign coeffs[1] = 8'd2;
    assign coeffs[2] = 8'd3;
    assign coeffs[3] = 8'd4;

    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 4; i = i + 1) begin
                delay_line[i] <= 8'd0;
                mul_results[i] <= 16'd0;
            end
            add_stage_1[0] <= 16'd0;
            add_stage_1[1] <= 16'd0;
            add_stage_2 <= 16'd0;
            y <= 16'd0;
        end else begin
            // Shift the delay line
            for (i = 3; i > 0; i = i - 1) begin
                delay_line[i] <= delay_line[i-1];
            end
            delay_line[0] <= x;

            // Multiply coefficients
            for (i = 0; i < 4; i = i + 1) begin
                mul_results[i] <= delay_line[i] * coeffs[i];
            end

            // Add stage 1
            add_stage_1[0] <= mul_results[0] + mul_results[1];
            add_stage_1[1] <= mul_results[2] + mul_results[3];

            // Add stage 2
            add_stage_2 <= add_stage_1[0] + add_stage_1[1];

            // Output result
            y <= add_stage_2;
        end
    end

endmodule

module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

    reg [7:0] x_reg [0:3];
    reg [15:0] y_reg [0:2];
    reg [15:0] coeff [0:3];
    integer i;

    initial begin
        coeff[0] = 16'd1;
        coeff[1] = 16'd2;
        coeff[2] = 16'd3;
        coeff[3] = 16'd4;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 4; i = i + 1) begin
                x_reg[i] <= 8'd0;
            end
            for (i = 0; i < 3; i = i + 1) begin
                y_reg[i] <= 16'd0;
            end
            y <= 16'd0;
        end else begin
            x_reg[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                x_reg[i] <= x_reg[i-1];
            end

            y_reg[0] <= x_reg[0] * coeff[0] + x_reg[1] * coeff[1];
            y_reg[1] <= y_reg[0] + x_reg[2] * coeff[2];
            y_reg[2] <= y_reg[1] + x_reg[3] * coeff[3];
            y <= y_reg[2];
        end
    end

endmodule

module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

    parameter N = 4;
    reg [7:0] x_pipe [0:N-1];
    reg [15:0] y_pipe [0:N-1];
    reg [15:0] coeff [0:N-1];
    integer i;

    initial begin
        coeff[0] = 16'd1;
        coeff[1] = 16'd2;
        coeff[2] = 16'd3;
        coeff[3] = 16'd4;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < N; i = i + 1) begin
                x_pipe[i] <= 8'd0;
                y_pipe[i] <= 16'd0;
            end
            y <= 16'd0;
        end else begin
            x_pipe[0] <= x;
            y_pipe[0] <= x * coeff[0];
            for (i = 1; i < N; i = i + 1) begin
                x_pipe[i] <= x_pipe[i-1];
                y_pipe[i] <= y_pipe[i-1] + x_pipe[i] * coeff[i];
            end
            y <= y_pipe[N-1];
        end
    end

endmodule

