    input signed [7:0] in_1,
    output signed [15:0] out
);

    wire signed [15:0] term1, term2, term3, term4, term5;

    assign term1 = in_0 * in_0;          // in_0^2
    assign term2 = in_0 * in_1;          // in_0 * in_1
    assign term3 = in_1 * in_1;          // in_1^2
    assign term4 = in_0 << 3;            // 8 * in_0
    assign term5 = in_1 << 2;            // 4 * in_1

    assign out = term1 + term2 + term3 + term4 + term5;

endmodule

