module solve_problem(input wire clk, input wire reset, input wire [7:0] data_in, output reg [7:0] result);

  reg [7:0] temp;
  reg [3:0] i;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      result <= 8'b0;
      temp <= 8'b0;
      i <= 4'b0;
    end else begin
      temp <= data_in;
      for (i = 0; i < 8; i = i + 1) begin
        if (temp[i]) begin
          result <= i;
          i = 8; // Exit the loop by setting i to the max value
        end
      end
    end
  end

endmodule

module efficient_solver(input wire clk, input wire reset, input wire [7:0] in, output reg [7:0] out);

  reg [7:0] temp;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      temp <= 8'b0;
      out <= 8'b0;
    end else begin
      if (in > temp) begin
        temp <= in;
        out <= temp;
      end else begin
        out <= temp;
      end
    end
  end

