    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    wire signed [15:0] T = $signed(temperature);
    wire signed [15:0] R = $signed(humidity);

    wire signed [15:0] T2 = T * T;
    wire signed [15:0] R2 = R * R;
    wire signed [15:0] TR = T * R;
    wire signed [15:0] T2R = T2 * R;
    wire signed [15:0] TR2 = TR * R;
    wire signed [15:0] T2R2 = T2 * R2;

    assign heat_index = C1 + (C2 * T) + (C3 * R) + (C4 * TR) + (C5 * T2) + (C6 * R2) + (C7 * T2R) + (C8 * TR2) + (C9 * T2R2);

