    wire signed [31:0] T2R2 = T2 * R2;

    wire signed [31:0] term1 = C1 + (C2 * T) + (C3 * R);
    wire signed [31:0] term2 = (C4 * TR) + (C5 * T2) + (C6 * R2);
    wire signed [31:0] term3 = (C7 * T2R) + (C8 * TR2) + (C9 * T2R2);

    assign heat_index = term1 + term2 + term3;

endmodule

module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    reg signed [31:0] T; // Extended temperature
    reg signed [31:0] R; // Extended humidity
    reg signed [31:0] T2; // T^2
    reg signed [31:0] R2; // R^2
    reg signed [31:0] TR; // T * R
    reg signed [31:0] T2R; // T^2 * R
    reg signed [31:0] TR2; // T * R^2
    reg signed [31:0] T2R2; // T^2 * R^2

    reg signed [31:0] HI; // Heat index intermediate value

    always @(*) begin
        T = temperature;
        R = humidity;
        T2 = T * T;
        R2 = R * R;
        TR = T * R;
        T2R = T2 * R;
        TR2 = T * R2;
