        if (pm2_5 <= 12)
            aqi_pm2_5 = pm2_5 * 50 / 12;
        else if (pm2_5 <= 35)
            aqi_pm2_5 = 50 + (pm2_5 - 12) * 50 / 23;
        else if (pm2_5 <= 55)
            aqi_pm2_5 = 100 + (pm2_5 - 35) * 50 / 20;
        else if (pm2_5 <= 150)
            aqi_pm2_5 = 150 + (pm2_5 - 55) * 100 / 95;
        else if (pm2_5 <= 250)
            aqi_pm2_5 = 250 + (pm2_5 - 150) * 100 / 100;
        else
            aqi_pm2_5 = 400 + (pm2_5 - 250) * 100 / 150;

        // Calculate AQI for PM10
        if (pm10 <= 54)
            aqi_pm10 = pm10 * 50 / 54;
        else if (pm10 <= 154)
            aqi_pm10 = 50 + (pm10 - 54) * 50 / 100;
        else if (pm10 <= 254)
            aqi_pm10 = 100 + (pm10 - 154) * 50 / 100;
        else if (pm10 <= 354)
            aqi_pm10 = 150 + (pm10 - 254) * 100 / 100;
        else if (pm10 <= 424)
            aqi_pm10 = 250 + (pm10 - 354) * 100 / 70;
        else
            aqi_pm10 = 400 + (pm10 - 424) * 100 / 76;

        // Calculate AQI for NO2
        if (no2 <= 53)
            aqi_no2 = no2 * 50 / 53;
        else if (no2 <= 100)
            aqi_no2 = 50 + (no2 - 53) * 50 / 47;
        else if (no2 <= 360)
            aqi_no2 = 100 + (no2 - 100) * 50 / 260;
        else if (no2 <= 649)
            aqi_no2 = 150 + (no2 - 360) * 100 / 289;
        else if (no2 <= 1249)
            aqi_no2 = 250 + (no2 - 649) * 100 / 600;
        else
            aqi_no2 = 400 + (no2 - 1249) * 100 / 751;

        // Combine AQI values to determine final AQI
        aqi = (aqi_pm2_5 > aqi_pm10) ? 
              ((aqi_pm2_5 > aqi_no2) ? aqi_pm2_5 : aqi_no2) : 
              ((aqi_pm10 > aqi_no2) ? aqi_pm10 : aqi_no2);
